(1, 1, 'A WordPress Commenter', 'wapuu@wordpress.example', 'https://wordpress.org/', '', '2026-05-28 05:17:10', '2026-05-28 05:17:10', 'Hi, this is a comment.\nTo get started with moderating, editing, and deleting comments, please visit the Comments screen in the dashboard.\nCommenter avatars come from <a href=\"https://gravatar.com/\">Gravatar</a>.', 0, '1', '', 'comment', 0, 0);
INSERT INTO `wp_craftkit_widget_history` (`id`, `widget_name`, `widget_title`, `widget_description`, `widget_icon`, `widget_category`, `widget_code`, `registration_code`, `functions_code`, `created_at`) VALUES
(1, 'test', 'tst', '', 'eicon-heading', 'basic', '<?php\n/**\n * Widget Name: test\n * Description: \n * Author: CraftKit\n * Version: 1.0.0\n */\n\nif (!defined(\'ABSPATH\')) {\n    exit; // Exit if accessed directly.\n}\n\nclass Test_Widget extends \\Elementor\\Widget_Base {\n    // Required Methods\n    public function get_name() {\n        return \'test\';\n    }\n\n    public function get_title() {\n        return esc_html__(\'tst\', \'craftkit\');\n    }\n\n    public function get_icon() {\n        return \'eicon-heading\';\n    }\n\n    public function get_categories() {\n        return [\'basic\'];\n    }\n\n    public function get_style_depends() {\n        return [\'font-awesome\'];\n    }\n\n    // Controls\n    protected function register_controls() {\n        // Content Section\n        $this->start_controls_section(\n            \'content_section\',\n            [\n                \'label\' => esc_html__(\'Content\', \'craftkit\'),\n                \'tab\' => \\Elementor\\Controls_Manager::TAB_CONTENT,\n            ]\n        );\n\n        // dsd Control\n        $this->add_control(\n            \'sad\',\n            [\n                \'label\' => esc_html__(\'dsd\', \'craftkit\'),\n                \'type\' => \\Elementor\\Controls_Manager::TEXTAREA,\n                \'default\' => esc_html__(\'Enter your content here...\', \'craftkit\'),\n                \'dynamic\' => [ \'active\' => true ],\n            ]\n        );\n\n        // sas Control\n        $this->add_control(\n            \'ds\',\n            [\n                \'label\' => esc_html__(\'sas\', \'craftkit\'),\n                \'type\' => \\Elementor\\Controls_Manager::NUMBER,\n                \'dynamic\' => [ \'active\' => true ],\n            ]\n        );\n\n        $this->end_controls_section();\n\n        // Debug Information\n        // Total controls processed: 2\n        // Control 1: TEXTAREA - sad - dsd\n        // Control 2: NUMBER - ds - sas\n\n        // Style Section\n        $this->start_controls_section(\n            \'style_section\',\n            [\n                \'label\' => esc_html__(\'Style\', \'craftkit\'),\n                \'tab\' => \\Elementor\\Controls_Manager::TAB_STYLE,\n            ]\n        );\n\n        // dsd Style Controls\n        $this->add_control(\n            \'sad_style_heading\',\n            [\n                \'label\' => esc_html__(\'dsd Style\', \'craftkit\'),\n                \'type\' => \\Elementor\\Controls_Manager::HEADING,\n                \'separator\' => \'before\',\n            ]\n        );\n\n        // HTML Tag for sad\n        $this->add_control(\n            \'sad_tag\',\n            [\n                \'label\' => esc_html__(\'HTML Tag\', \'craftkit\'),\n                \'type\' => \\Elementor\\Controls_Manager::SELECT,\n                \'options\' => [\n                    \'div\' => \'div\',\n                    \'span\' => \'span\',\n                    \'p\' => \'p\',\n                ],\n                \'default\' => \'p\',\n            ]\n        );\n\n        // Alignment for sad\n        $this->add_responsive_control(\n            \'sad_align\',\n            [\n                \'label\' => esc_html__(\'Alignment\', \'craftkit\'),\n                \'type\' => \\Elementor\\Controls_Manager::CHOOSE,\n                \'options\' => [\n                    \'left\' => [\n                        \'title\' => esc_html__(\'Left\', \'craftkit\'),\n                        \'icon\' => \'eicon-text-align-left\',\n                    ],\n                    \'center\' => [\n                        \'title\' => esc_html__(\'Center\', \'craftkit\'),\n                        \'icon\' => \'eicon-text-align-center\',\n                    ],\n                    \'right\' => [\n                        \'title\' => esc_html__(\'Right\', \'craftkit\'),\n                        \'icon\' => \'eicon-text-align-right\',\n                    ],\n                    \'justify\' => [\n                        \'title\' => esc_html__(\'Justify\', \'craftkit\'),\n                        \'icon\' => \'eicon-text-align-justify\',\n                    ],\n                ],\n                \'default\' => \'left\',\n                \'selectors\' => [\n                    \'{{WRAPPER}} .test-widget .widget-sad\' => \'text-align: {{VALUE}};\',\n                ],\n            ]\n        );\n\n        // Typography for sad\n        $this->add_group_control(\n            \\Elementor\\Group_Control_Typography::get_type(),\n            [\n                \'name\' => \'sad_typography\',\n                \'selector\' => \'{{WRAPPER}} .test-widget .widget-sad\',\n            ]\n        );\n\n        // Text Stroke for sad\n        $this->add_group_control(\n            \\Elementor\\Group_Control_Text_Stroke::get_type(),\n            [\n                \'name\' => \'sad_text_stroke\',\n                \'selector\' => \'{{WRAPPER}} .test-widget .widget-sad\',\n            ]\n        );\n\n        // Margin for sad\n        $this->add_responsive_control(\n            \'sad_margin\',\n            [\n                \'label\' => esc_html__(\'Margin\', \'craftkit\'),\n                \'type\' => \\Elementor\\Controls_Manager::DIMENSIONS,\n                \'size_units\' => [\'px\', \'em\', \'rem\', \'%\'],\n                \'selectors\' => [\n                    \'{{WRAPPER}} .test-widget .widget-sad\' => \'margin: {{TOP}}{{UNIT}} {{RIGHT}}{{UNIT}} {{BOTTOM}}{{UNIT}} {{LEFT}}{{UNIT}};\',\n                ],\n            ]\n        );\n\n        // Padding for sad\n        $this->add_responsive_control(\n            \'sad_padding\',\n            [\n                \'label\' => esc_html__(\'Padding\', \'craftkit\'),\n                \'type\' => \\Elementor\\Controls_Manager::DIMENSIONS,\n                \'size_units\' => [\'px\', \'em\', \'rem\', \'%\'],\n                \'selectors\' => [\n                    \'{{WRAPPER}} .test-widget .widget-sad\' => \'padding: {{TOP}}{{UNIT}} {{RIGHT}}{{UNIT}} {{BOTTOM}}{{UNIT}} {{LEFT}}{{UNIT}};\',\n                ],\n            ]\n        );\n\n        // Color for sad\n        $this->add_control(\n            \'sad_color\',\n            [\n                \'label\' => esc_html__(\'Color\', \'craftkit\'),\n                \'type\' => \\Elementor\\Controls_Manager::COLOR,\n                \'selectors\' => [\n                    \'{{WRAPPER}} .test-widget .widget-sad\' => \'color: {{VALUE}};\',\n                ],\n            ]\n        );\n\n        // Text Shadow for sad\n        $this->add_group_control(\n            \\Elementor\\Group_Control_Text_Shadow::get_type(),\n            [\n                \'name\' => \'sad_text_shadow\',\n                \'selector\' => \'{{WRAPPER}} .test-widget .widget-sad\',\n            ]\n        );\n\n        // sas Style Controls\n        $this->add_control(\n            \'ds_style_heading\',\n            [\n                \'label\' => esc_html__(\'sas Style\', \'craftkit\'),\n                \'type\' => \\Elementor\\Controls_Manager::HEADING,\n                \'separator\' => \'before\',\n            ]\n        );\n\n        // HTML Tag for ds\n        $this->add_control(\n            \'ds_tag\',\n            [\n                \'label\' => esc_html__(\'HTML Tag\', \'craftkit\'),\n                \'type\' => \\Elementor\\Controls_Manager::SELECT,\n                \'options\' => [\n                    \'h1\' => \'H1\',\n                    \'h2\' => \'H2\',\n                    \'h3\' => \'H3\',\n                    \'h4\' => \'H4\',\n                    \'h5\' => \'H5\',\n                    \'h6\' => \'H6\',\n                    \'div\' => \'div\',\n                    \'span\' => \'span\',\n                    \'p\' => \'p\',\n                ],\n                \'default\' => \'h2\',\n            ]\n        );\n\n        // Alignment for ds\n        $this->add_responsive_control(\n            \'ds_align\',\n            [\n                \'label\' => esc_html__(\'Alignment\', \'craftkit\'),\n                \'type\' => \\Elementor\\Controls_Manager::CHOOSE,\n                \'options\' => [\n                    \'left\' => [\n                        \'title\' => esc_html__(\'Left\', \'craftkit\'),\n                        \'icon\' => \'eicon-text-align-left\',\n                    ],\n                    \'center\' => [\n                        \'title\' => esc_html__(\'Center\', \'craftkit\'),\n                        \'icon\' => \'eicon-text-align-center\',\n                    ],\n                    \'right\' => [\n                        \'title\' => esc_html__(\'Right\', \'craftkit\'),\n                        \'icon\' => \'eicon-text-align-right\',\n                    ],\n                    \'justify\' => [\n                        \'title\' => esc_html__(\'Justify\', \'craftkit\'),\n                        \'icon\' => \'eicon-text-align-justify\',\n                    ],\n                ],\n                \'default\' => \'left\',\n                \'selectors\' => [\n                    \'{{WRAPPER}} .test-widget .widget-ds\' => \'text-align: {{VALUE}};\',\n                ],\n            ]\n        );\n\n        // Typography for ds\n        $this->add_group_control(\n            \\Elementor\\Group_Control_Typography::get_type(),\n            [\n                \'name\' => \'ds_typography\',\n                \'selector\' => \'{{WRAPPER}} .test-widget .widget-ds\',\n            ]\n        );\n\n        // Text Stroke for ds\n        $this->add_group_control(\n            \\Elementor\\Group_Control_Text_Stroke::get_type(),\n            [\n                \'name\' => \'ds_text_stroke\',\n                \'selector\' => \'{{WRAPPER}} .test-widget .widget-ds\',\n            ]\n        );\n\n        // Color for ds\n        $this->add_control(\n            \'ds_color\',\n            [\n                \'label\' => esc_html__(\'Color\', \'craftkit\'),\n                \'type\' => \\Elementor\\Controls_Manager::COLOR,\n                \'selectors\' => [\n                    \'{{WRAPPER}} .test-widget .widget-ds\' => \'color: {{VALUE}};\',\n                ],\n            ]\n        );\n\n        // Text Shadow for ds\n        $this->add_group_control(\n            \\Elementor\\Group_Control_Text_Shadow::get_type(),\n            [\n                \'name\' => \'ds_text_shadow\',\n                \'selector\' => \'{{WRAPPER}} .test-widget .widget-ds\',\n            ]\n        );\n\n        // Margin for ds\n        $this->add_responsive_control(\n            \'ds_margin\',\n            [\n                \'label\' => esc_html__(\'Margin\', \'craftkit\'),\n                \'type\' => \\Elementor\\Controls_Manager::DIMENSIONS,\n                \'size_units\' => [\'px\', \'em\', \'rem\', \'%\'],\n                \'selectors\' => [\n                    \'{{WRAPPER}} .test-widget .widget-ds\' => \'margin: {{TOP}}{{UNIT}} {{RIGHT}}{{UNIT}} {{BOTTOM}}{{UNIT}} {{LEFT}}{{UNIT}};\',\n                ],\n            ]\n        );\n\n        // Padding for ds\n        $this->add_responsive_control(\n            \'ds_padding\',\n            [\n                \'label\' => esc_html__(\'Padding\', \'craftkit\'),\n                \'type\' => \\Elementor\\Controls_Manager::DIMENSIONS,\n                \'size_units\' => [\'px\', \'em\', \'rem\', \'%\'],\n                \'selectors\' => [\n                    \'{{WRAPPER}} .test-widget .widget-ds\' => \'padding: {{TOP}}{{UNIT}} {{RIGHT}}{{UNIT}} {{BOTTOM}}{{UNIT}} {{LEFT}}{{UNIT}};\',\n                ],\n            ]\n        );\n\n        $this->end_controls_section();\n    }\n\n    // Render\n    protected function render() {\n        $settings = $this->get_settings_for_display();\n        echo \'<div class=\"test-widget\">\';\n        if (!empty($settings[\'sad\'])) {\n            $tag = !empty($settings[\'sad_tag\']) ? $settings[\'sad_tag\'] : \'p\';\n            echo \'<\' . esc_attr($tag) . \' class=\"widget-sad\">\' . esc_html($settings[\'sad\']) . \'</\' . esc_attr($tag) . \'>\';\n        }\n        if (!empty($settings[\'ds\'])) {\n            $tag = !empty($settings[\'ds_tag\']) ? $settings[\'ds_tag\'] : \'h2\';\n            echo \'<\' . esc_attr($tag) . \' class=\"widget-ds\">\' . esc_html($settings[\'ds\']) . \'</\' . esc_attr($tag) . \'>\';\n        }\n        echo \'</div>\';\n    }\n}\n', '<?php\n\n/**\n * Elementor Widgets Registration\n * \n * This file registers all custom Elementor widgets\n * \n * @package ElementorAddon\n * @version 1.0.0\n */\n\n// Prevent direct access\nif (!defined(\'ABSPATH\')) {\n    exit; // Exit if accessed directly.\n}\n\n/**\n * Register Custom Elementor Widgets\n * \n * @param \\Elementor\\Widgets_Manager $widgets_manager Elementor widgets manager.\n */\nfunction register_project_elementor_widgets($widgets_manager) {\n\n    // Require widget files\n    require_once(__DIR__ . \'/widgets/test.php\');\n\n    // Register widget classes\n    $widgets_manager->register(new \\Test_Widget());\n\n}\n\n// Hook into Elementor widgets registration\nadd_action(\'elementor/widgets/register\', \'register_project_elementor_widgets\');\n', '/**\n * Elementor Custom Widgets Integration\n * \n * Add this code to your theme\'s functions.php file\n * or in your custom plugin file\n */\n\n// Include Elementor Custom Widgets\nrequire_once get_stylesheet_directory() . \'/elementor-addon/elementor-widgets.php\';\n', '2026-06-16 13:51:57');
